window.addEventListener('catalog-ready',()=>{document.querySelector('#latest-grid').innerHTML=[...catalog].sort((a,b)=>b.date.localeCompare(a.date)||Number(b.id)-Number(a.id)).slice(0,3).map(s=>`<a class="latest-item" href="#sermao/${s.slug}"><div class="latest-image"><img src="${s.cover||sermonCovers[s.id]||'assets/banners/novo-2.webp'}" alt="" loading="lazy"><span>${esc(s.book||s.category)}</span></div><div class="latest-meta">${new Date(s.date).toLocaleDateString('pt-BR')} · ${s.minutes} MIN DE LEITURA</div><h3>${esc(s.title)}</h3><p>${esc(s.author)} </p></a>`).join('')});
